function debounce(fn, ms) {
  let timer;

  function debounced(...args) {
    clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      fn.apply(this, args);
    }, ms);
  }

  debounced.cancel = () => {
    clearTimeout(timer);
    timer = null;
  };

  return debounced;
}

// Usage
const log = debounce((msg) => console.log(msg), 500);

log("first");   // won't fire
log("second");  // resets timer; only "second" fires after 500ms

setTimeout(() => log.cancel(), 400); // cancel before "second" fires → nothing logged
